/*
	VIOC_capital_reinforce.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "capital_reinforce" (2026-10-17). Solo servidor: init.sqf lo lanza con execVM (en la partida LAN el anfitrion es
	el servidor y la consola LOCAL EXEC llega aqui). Sirve para las misiones A y B y para cualquier mapa: la capital es la de
	towns_capital (VIOC_TC_CAPITAL; Tanoa: Georgetown) o, sin ese parche, el pueblo con mas maxSV.

	Parametros de lobby:
	  VIOC_CAPITAL_REINF        0 = no / 5 / 10 (por defecto) / 15: cada cuantos minutos se revisa la capital.
	  VIOC_CAPITAL_REINF_MIN    10 / 20 (por defecto) / 30: defensores vivos del duenio a 600 m por debajo de los que llegan refuerzos.
	  VIOC_CAPITAL_REINF_MAX    2 / 3 (por defecto) / 4: grupos de refuerzo vivos a la vez (tope).
	  VIOC_CAPITAL_AI_PRIORITY  0 = no / 1 = el duenio la defiende / 2 = la defiende y el otro bando la ataca (por defecto).

	1) REFUERZOS PERIODICOS. Cada VIOC_CAPITAL_REINF min, si la capital tiene duenio (Oeste, Este o la guerrilla) y sus
	   defensores vivos a VIOC_CR_RANGE m (IA del duenio: guarnicion de BECTI, tiradores de estaticas, escuadras, refuerzos)
	   mas los refuerzos que ya vienen en camino no llegan al minimo, llega UN grupo de 6-8 hombres de la infanteria de pueblo
	   del duenio (<TAG>INFANTRY_SQ_LIGHT/MG/AT, con CTI_CO_FNC_CreateTeam: armas, ropa y voces de los demas parches).
	   - De donde: en camion (fabrica ligera del bando que ya puede comprar sin investigar; la guerrilla, un Zamak civil)
	     desde la base (la estructura propia mas cercana o el HQ) o desde el pueblo propio mas cercano, a 1,2-6 km, si se
	     llega por tierra (en linea recta no mas de 350 m de agua seguida) y hay un camino cerca sin jugadores a 500 m ni a
	     la vista; se bajan en una entrada de la capital (camino a 280-450 m del centro, del lado de donde vienen). Si no hay
	     camion o sitio: a pie desde un punto oculto a 600-900 m (tierra, sin jugadores a 500 m ni a la vista, sin enemigos a
	     300 m, lejos de pueblos de otro duenio y del HQ enemigo). Las entradas cambian: se evitan los rumbos de las 2 ultimas.
	     El camion se baja antes si lo atacan (enemigos a 300 m), se atasca (1 min sin avanzar 20 m), se rompe o tarda mas de 18 min.
	   - Al llegar: defienden una posicion al azar dentro de la capital: estaticas del pueblo sin tirador, un control de
	     carretera de towns_capital o un grupo de edificios (lambs_wp_fnc_taskGarrison si LAMBS esta cargado: edificios y
	     estaticas vacias a 60 m; si no, estaticas y posiciones de edificios a mano). Si se alejan mas de 520 m sin enemigos
	     cerca, vuelven a su posicion.
	   - Topes: VIOC_CAPITAL_REINF_MAX grupos y 8 hombres por grupo; presupuesto de IA de perf_cleanup (VIOC_PERF_AI_MAX menos
	     la IA viva menos VIOC_CR_RESERVE) y reserva en VIOC_PERF_AI_COUNT como VIOC_IW_fnc_reserve.
	   - Mision B (mission_b_rules): si la capital es del Oeste con vioc_mb_key y vioc_mb_hold vigente, la mision B ya
	     mantiene la guarnicion de BECTI: solo hay refuerzos si esa guarnicion existe desde hace 2 min y aun asi los
	     defensores no llegan al minimo (la guarnicion se gasto peleando). Mientras la rehace, nada.
	   - Aviso al duenio (Oeste/Este): "Refuerzos en camino a <capital> (...)", como mucho uno cada 2 min por bando.
	2) PRIORIDAD PARA LA IA (VIOC_CAPITAL_AI_PRIORITY; equipos IA de BECTI, orden de la mision cti_order):
	   - Defensa: con 3 o mas enemigos de tierra a menos de 800 m del centro (sin contar la guarnicion de otro pueblo a 300 m
	     de su centro), el bando duenio (Oeste/Este) manda 1 escuadra IA (la mas cercana a menos de 5 km, por tierra, sin
	     combate a 300 m, que no este por tomar otro pueblo) con CTI_ORDER_HOLDTOWNSBASE sobre la capital (patrulla y defensa
	     de la propia mision). Si el comandante IA la reparte a otro pueblo (Update_Orders cada 10 min) mientras dura la
	     amenaza, se le vuelve a poner la capital. Termina 4 min sin amenaza, a los 25 min o si se pierde la capital: vuelve a
	     su orden (las automaticas como TAKETOWNS, para que la mision elija de nuevo). 5 min de espera entre envios.
	   - Ataque (opcion 2): cada 10 min desde el minuto 20, el bando (Oeste/Este) que NO tiene la capital manda hasta 2
	     escuadras libres (ordenes automaticas de tomar pueblos, a menos de 5 km, por tierra, como mucho el 40 % de sus
	     escuadras de tierra) con CTI_ORDER_TAKETOWN (o TAKEHOLDTOWN) sobre la capital. No se duplica: nada si ai_tactics ya
	     tiene una maniobra o un contraataque pendiente de ese bando sobre la capital (contraataques del que la perdio y la
	     ofensiva de la mision B), si ya van 2 escuadras o si sus hombres no llegan a la mitad de los defensores (con 10 o mas
	     defensores hacen falta 2 escuadras). Al tomarla, la mision devuelve sola la orden; a los 25 min sin tomarla vuelven
	     a TAKETOWNS. ai_tactics puede convertir 2 escuadras que van al mismo pueblo en una pinza (se respeta).
	   - Con un jugador de comandante solo se usan escuadras con ordenes automaticas (como ai_tactics). Nunca: grupos con
	     jugadores, el del comandante, aereos, operaciones especiales, ai_transport, maniobras de ai_tactics.
	   - Aviso al bando que manda la escuadra: "[Capital] ...", con la misma espera de 2 min.
	3) LIMPIEZA: si el duenio pierde la capital, sus refuerzos siguen peleando donde esten (el camion que viene los baja ya) y
	   se borran pasados 5 min cuando no hay jugadores a 1 km; si la recupera antes, vuelven a su posicion. Un grupo que en
	   30 min nunca llego a 600 m de la capital se borra lejos de jugadores. El camion vuelve por donde vino y se borra (con
	   su conductor) cuando no hay jugadores a 600 m (despues de 20 min, a 150 m); si un jugador lo toma, es suyo. Nada se
	   guarda: los grupos no se guardan nunca y el camion lleva vioc_cr (filtro en Server_SaveToProfile.sqf).
	   Los grupos llevan cti_funds = 0 (sin fondos ni equipo de BECTI: solo para que Server_OperateTownDefensesUnits.sqf,
	   al desactivarse el pueblo, no borre a los que tripulan estaticas del pueblo).
	Consola (LOCAL EXEC en el anfitrion):
	  hint (call VIOC_CR_fnc_info);          estado: duenio, defensores, grupos, camiones, defensa y ataque de la IA
	  hint (call VIOC_CR_fnc_force);         un grupo de refuerzo YA (sin mirar el minimo ni la espera; con los topes)
	  call VIOC_CR_fnc_markers;              marcadores locales de grupos, posiciones y camiones (otra vez: borrar)
	  hint (call VIOC_CR_fnc_forceDefense);  el duenio manda YA una escuadra a defenderla (sin mirar la amenaza)
	  hint ([east] call VIOC_CR_fnc_forceAttack);   ese bando manda YA escuadras a tomarla (sin la espera ni la proporcion)
*/
if (!isServer) exitWith {};
if (!isNil "VIOC_CR_RUNNING") exitWith {};
VIOC_CR_RUNNING = true;

//--- Ajustes
VIOC_CR_RANGE = 600;              // m: defensores vivos del duenio que cuentan (alrededor del centro de la capital)
VIOC_CR_SIZE = [6, 8];            // hombres por grupo de refuerzo
VIOC_CR_MEN_GROUP = 8;            // hombres por grupo para el tope de hombres (grupos x esto)
VIOC_CR_RESERVE = 30;             // plazas del presupuesto de IA (perf_cleanup) que se dejan libres
VIOC_CR_FIRST = 90;               // s tras el arranque: primera revision
VIOC_CR_RETRY = 120;              // s: nueva revision si no se pudo mandar (sin sitio o sin presupuesto)
VIOC_CR_TICK = 10;                // s por pasada del bucle
VIOC_CR_FOOT_R = [750, 650, 850, 600, 900]; // m del centro: punto oculto de los que llegan a pie
VIOC_CR_SRC_R = [1200, 6000];     // m: base o pueblo propio desde el que sale el camion
VIOC_CR_SRC_ROAD = 300;           // m: caminos alrededor de la base o del pueblo de salida
VIOC_CR_DROP_R = [280, 450];      // m del centro: donde se baja la gente del camion (un camino de entrada)
VIOC_CR_DROP_ARC = 80;            // grados a cada lado del rumbo hacia el lugar de salida
VIOC_CR_PLAYER = 500;             // m sin jugadores alrededor del lugar donde aparecen
VIOC_CR_VIS = 1500;               // m: jugadores que podrian verlo aparecer (checkVisibility)
VIOC_CR_ENEMY = 300;              // m sin enemigos alrededor del lugar donde aparecen
VIOC_CR_ENEMY_TOWN = 400;         // m de pueblos de otro duenio
VIOC_CR_ENEMY_HQ = 1200;          // m del HQ enemigo
VIOC_CR_ENTRY_SEP = 50;           // grados entre una entrada y las 2 anteriores
VIOC_CR_RIDE_MAX = 1080;          // s en camion como mucho (despues se bajan y siguen a pie)
VIOC_CR_STUCK = 60;               // s sin avanzar 20 m: se bajan
VIOC_CR_CONTACT = 300;            // m: enemigos cerca del camion -> se bajan a pelear
VIOC_CR_ARRIVE = 60;              // m: llegaron (al punto de bajada o a su posicion)
VIOC_CR_WALK_MAX = 1500;          // s a pie: despues se ponen en posicion desde donde esten
VIOC_CR_LOST = 1800;              // s: grupo que nunca llego a VIOC_CR_RANGE de la capital -> se borra lejos de jugadores
VIOC_CR_GARRISON_R = 60;          // m: radio de la posicion (edificios y estaticas)
VIOC_CR_STRAY = 520;              // m del centro: un grupo en posicion que se alejo tanto vuelve (sin amenaza)
VIOC_CR_ORPHAN_DELAY = 300;       // s tras perder la capital antes de borrar los refuerzos que quedan
VIOC_CR_FREE = 1000;              // m sin jugadores para borrar refuerzos sobrantes
VIOC_CR_TRUCK_FREE = 600;         // m sin jugadores para borrar un camion que ya dejo su carga
VIOC_CR_TRUCK_MAXT = 1200;        // s: despues, se borra con solo 150 m sin jugadores
VIOC_CR_MSG_GAP = 120;            // s entre avisos al mismo bando
VIOC_CR_GUER_TRUCKS = ["C_Truck_02_covered_F", "C_Truck_02_transport_F"]; // Zamak civil de Arma 3 (soft_f_beta, 14 pasajeros)
//--- prioridad para la IA
VIOC_CR_THREAT_R = 800;           // m: enemigos a esta distancia del centro = amenaza
VIOC_CR_THREAT_MIN = 3;           // enemigos de tierra para que cuente
VIOC_CR_TOWN_EXCL = 300;          // m: enemigos tan cerca del centro de otro pueblo son su guarnicion (si estan a mas de 450 m de la capital)
VIOC_CR_DEF_RANGE = 5000;         // m: escuadras del duenio que pueden ir a defenderla
VIOC_CR_DEF_TEAMS = 1;            // escuadras a la vez defendiendo la capital por este parche
VIOC_CR_DEF_COOLDOWN = 300;       // s entre envios
VIOC_CR_DEF_CALM = 240;           // s sin amenaza: la escuadra vuelve a su orden
VIOC_CR_DEF_MAXT = 1500;          // s como mucho
VIOC_CR_ATK_START = 1200;         // s tras el arranque antes del primer ataque prioritario
VIOC_CR_ATK_PERIOD = 600;         // s entre revisiones del ataque
VIOC_CR_ATK_RANGE = 5000;         // m: escuadras que pueden ir
VIOC_CR_ATK_TEAMS = 2;            // escuadras hacia la capital (contando las que ya van)
VIOC_CR_ATK_MAXT = 1500;          // s: despues, si no la tomaron, vuelven a TAKETOWNS
VIOC_CR_ATK_SHARE = 0.4;          // parte maxima de las escuadras de tierra del bando
VIOC_CR_HOLD_PENALTY = 1500;      // m de mas al elegir escuadras que defienden otro sitio (HOLD)
VIOC_CR_WATER_GAP = 350;          // m de agua seguida en linea recta que todavia se acepta (puentes)

VIOC_CR_CAP = objNull;
VIOC_CR_PERIOD = 10;
VIOC_CR_MIN = 20;
VIOC_CR_MAXG = 3;
VIOC_CR_PRIO = 2;
VIOC_CR_GROUPS = [];              // refuerzos (hashmaps)
VIOC_CR_TRUCKS = [];              // camiones que ya dejaron su carga (hashmaps)
VIOC_CR_DEF = [];                 // escuadras IA defendiendo la capital (hashmaps)
VIOC_CR_ATK = [];                 // escuadras IA atacando la capital (hashmaps)
VIOC_CR_ENTRY = [];               // rumbos (desde el centro) de las ultimas entradas
VIOC_CR_LASTKIND = "";
VIOC_CR_NEXT = -1;
VIOC_CR_ATK_NEXT = -1;
VIOC_CR_T0 = -1;
VIOC_CR_LAST = "todavia ninguna";
VIOC_CR_THREAT = [sideUnknown, 0, -1];
VIOC_CR_DEF_NEXT = createHashMap;
VIOC_CR_MSG_T = createHashMap;
VIOC_CR_ARMED_C = createHashMap;
VIOC_CR_MK = [];
VIOC_CR_INFO = [0, 0, 0, 0, 0, 0, 0, 0]; // [grupos enviados, en camion, a pie, hombres, grupos borrados, camiones borrados, defensas IA, ataques IA]

//--- ---------------------------------- utilidades ----------------------------------
VIOC_CR_fnc_log = {
	params ["_m"];
	diag_log format ["[VIOC capital_reinforce] %1", _m];
};

VIOC_CR_fnc_stat = {
	params ["_i", ["_n", 1]];
	VIOC_CR_INFO set [_i, (VIOC_CR_INFO select _i) + _n];
};

VIOC_CR_fnc_p0 = {
	private _p = if (_this isEqualType objNull) then {getPosATL _this} else {_this};
	[_p select 0, _p select 1, 0]
};

VIOC_CR_fnc_tname = {
	params ["_t"];
	if (isNull _t) exitWith {"?"};
	_t getVariable ["cti_town_name", "?"]
};

VIOC_CR_fnc_sideName = {
	params ["_side"];
	switch (_side) do {
		case west: {"Oeste"};
		case east: {"Este"};
		case resistance: {"la guerrilla"};
		default {"nadie"};
	}
};

VIOC_CR_fnc_dirName = {
	params ["_b"];
	private _n = (round ((((_b % 360) + 360) % 360) / 45)) % 8;
	["el norte", "el noreste", "el este", "el sureste", "el sur", "el suroeste", "el oeste", "el noroeste"] select _n
};

VIOC_CR_fnc_angDiff = {
	params ["_a", "_b"];
	abs (((((_a - _b) % 360) + 540) % 360) - 180)
};

//--- Jugadores reales (sin clientes sin cabeza)
VIOC_CR_fnc_players = {
	allPlayers select {alive _x && {!(_x isKindOf "HeadlessClient_F")}}
};

//--- [objetos, radio] -> true si ningun jugador esta a menos del radio de alguno
VIOC_CR_fnc_farFromPlayers = {
	params ["_objs", "_r"];
	private _pl = call VIOC_CR_fnc_players;
	(_objs findIf {private _o = _x; (_pl findIf {(_x distance2D _o) < _r}) >= 0}) < 0
};

//--- [lugar] -> true si ningun jugador a VIOC_CR_VIS m lo ve (linea de vista)
VIOC_CR_fnc_unseen = {
	params ["_p"];
	private _asl = (AGLToASL _p) vectorAdd [0, 0, 1.5];
	((call VIOC_CR_fnc_players) findIf {((_x distance2D _p) < VIOC_CR_VIS) && {([vehicle _x, "VIEW", _x] checkVisibility [eyePos _x, _asl]) > 0.1}}) < 0
};

//--- [bando, texto]: aviso a los jugadores de ese bando (Oeste/Este), como mucho uno cada VIOC_CR_MSG_GAP s
VIOC_CR_fnc_say = {
	params ["_side", "_txt"];
	if !(_side in [west, east]) exitWith {[format ["(%1, sin jugadores) %2", _side, _txt]] call VIOC_CR_fnc_log};
	private _k = str _side;
	if ((time - (VIOC_CR_MSG_T getOrDefault [_k, -1e9])) < VIOC_CR_MSG_GAP) exitWith {[format ["(%1, sin aviso: muy seguido) %2", _side, _txt]] call VIOC_CR_fnc_log};
	VIOC_CR_MSG_T set [_k, time];
	_txt remoteExec ["systemChat", _side];
	[format ["(%1) %2", _side, _txt]] call VIOC_CR_fnc_log;
};

//--- [desde, hasta] -> true si en linea recta no hay mas de VIOC_CR_WATER_GAP m de agua seguida (muestra cada 50 m)
VIOC_CR_fnc_dry = {
	params ["_a", "_b"];
	private _d = _a distance2D _b;
	private _n = ceil (_d / 50);
	private _step = _d / (_n max 1);
	private _run = 0;
	private _ok = true;
	for "_i" from 1 to (_n - 1) do {
		private _p = [(_a select 0) + ((_b select 0) - (_a select 0)) * _i / _n, (_a select 1) + ((_b select 1) - (_a select 1)) * _i / _n];
		_run = if (surfaceIsWater _p) then {_run + _step} else {0};
		if (_run > VIOC_CR_WATER_GAP) exitWith {_ok = false};
	};
	_ok
};

//--- [centro, radios, rumbo] -> punto en tierra y dentro del mapa (rumbo +-45 grados) o []
VIOC_CR_fnc_landPoint = {
	params ["_c", "_radii", "_b"];
	private _res = [];
	private _ws = worldSize;
	{
		private _off = _x;
		{
			private _p = _c getPos [_x, _b + _off];
			if (!(surfaceIsWater _p) && {(_p select 0) > 50} && {(_p select 1) > 50} && {(_p select 0) < (_ws - 50)} && {(_p select 1) < (_ws - 50)}) exitWith {_res = [_p select 0, _p select 1, 0]};
		} forEach _radii;
		if (count _res > 0) exitWith {};
	} forEach [0, 15, -15, 30, -30, 45, -45];
	_res
};

//--- Plazas libres del presupuesto de IA (perf_cleanup; sin el, 650 menos la IA viva), menos VIOC_CR_RESERVE
VIOC_CR_fnc_room = {
	private _max = missionNamespace getVariable ["VIOC_PERF_AI_MAX", -1];
	private _cnt = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", -1];
	if (!(_max isEqualType 0) || {!(_cnt isEqualType 0)} || {_max < 0} || {_cnt < 0}) then {_max = 650; _cnt = {!isPlayer _x} count allUnits};
	_max - _cnt - VIOC_CR_RESERVE
};

//--- [hombres]: los suma al recuento de IA de perf_cleanup hasta su proximo recuento (como VIOC_IW_fnc_reserve)
VIOC_CR_fnc_reserve = {
	params ["_n"];
	isNil {
		private _c = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", -1];
		if ((_c isEqualType 0) && {_c >= 0}) then {missionNamespace setVariable ["VIOC_PERF_AI_COUNT", _c + _n]};
	};
};

VIOC_CR_fnc_clearWp = {
	params ["_g"];
	for "_i" from ((count (waypoints _g)) - 1) to 0 step -1 do {deleteWaypoint [_g, _i]};
};

VIOC_CR_fnc_hostiles = {
	params ["_side"];
	[west, east, resistance] - [_side]
};

//--- [lugar, radio, bando] -> hombres y vehiculos con gente de bandos enemigos a menos del radio
VIOC_CR_fnc_enemiesNear = {
	params ["_p", "_r", "_side"];
	private _hs = [_side] call VIOC_CR_fnc_hostiles;
	{alive _x && {(side _x) in _hs}} count (_p nearEntities [["CAManBase", "LandVehicle"], _r])
};

//--- [bando] -> IA viva de ese bando a VIOC_CR_RANGE m del centro de la capital (tambien dentro de vehiculos y estaticas)
VIOC_CR_fnc_defenders = {
	params ["_side"];
	private _c = VIOC_CR_CAP call VIOC_CR_fnc_p0;
	{alive _x && {!isPlayer _x} && {(side group _x) isEqualTo _side} && {(_x distance2D _c) < VIOC_CR_RANGE}} count allUnits
};

//--- [bando duenio] -> enemigos de tierra a VIOC_CR_THREAT_R m del centro (sin la guarnicion de otro pueblo cercano)
VIOC_CR_fnc_threat = {
	params ["_side"];
	private _c = VIOC_CR_CAP call VIOC_CR_fnc_p0;
	private _hs = [_side] call VIOC_CR_fnc_hostiles;
	private _others = CTI_Towns - [VIOC_CR_CAP];
	private _n = 0;
	{
		if (alive _x && {(side _x) in _hs} && {((getPosATL _x) select 2) < 40}) then {
			private _p = getPosATL _x;
			if (((_p distance2D _c) < 450) || {(_others findIf {(_x distance2D _p) < VIOC_CR_TOWN_EXCL}) < 0}) then {
				_n = _n + (if (_x isKindOf "CAManBase") then {1} else {({alive _x} count (crew _x)) max 1});
			};
		};
	} forEach (_c nearEntities [["CAManBase", "LandVehicle"], VIOC_CR_THREAT_R]);
	_n
};

//--- [bando] -> grupo del comandante (o grpNull)
VIOC_CR_fnc_cmd = {
	params ["_side"];
	private _c = (_side) call CTI_CO_FNC_GetSideCommander;
	if (isNil "_c") then {_c = grpNull};
	if !(_c isEqualType grpNull) then {_c = grpNull};
	_c
};

//--- [unidad, radio] -> true si conoce un enemigo a menos de radio
VIOC_CR_fnc_inCombat = {
	params ["_u", "_r"];
	private _e = _u findNearestEnemy _u;
	!isNull _e && {(_e distance _u) < _r}
};

//--- Capital: la de towns_capital; si no, su regla (VIOC_TC_fnc_findCapital) o el pueblo con mas maxSV base
VIOC_CR_fnc_findCapital = {
	private _c = missionNamespace getVariable ["VIOC_TC_CAPITAL", objNull];
	if (isNull _c && {!isNil "VIOC_TC_fnc_findCapital"}) then {_c = call VIOC_TC_fnc_findCapital};
	if (isNil "_c" || {!(_c isEqualType objNull)}) then {_c = objNull};
	if (isNull _c) then {
		private _best = -1;
		{
			private _sv = _x getVariable ["vioc_site_maxSV0", _x getVariable ["cti_town_maxSV", 0]];
			if (_sv isEqualType 0 && {_sv > _best} && {(_x getVariable ["vioc_site_mult", 1]) < 2}) then {_best = _sv; _c = _x};
		} forEach CTI_Towns;
	};
	_c
};

//--- ---------------------------------- unidades y vehiculos ----------------------------------
VIOC_CR_fnc_tag = {
	params ["_side"];
	["GUER_", "WEST_", "EAST_"] select (([resistance, west, east] find _side) max 0)
};

//--- [listas de missionNamespace] -> clases (las listas de pueblo son [clase, n], [clase, n, x] o "clase")
VIOC_CR_fnc_pool = {
	params ["_vars"];
	private _r = [];
	{
		private _l = missionNamespace getVariable [_x, []];
		if (_l isEqualType []) then {
			{
				private _c = if (_x isEqualType []) then {_x param [0, ""]} else {_x};
				if (_c isEqualType "" && {isClass (configFile >> "CfgVehicles" >> _c)}) then {_r pushBackUnique _c};
			} forEach _l;
		};
	} forEach _vars;
	_r
};

//--- [bando, hombres] -> clases del grupo (el 1.o es el jefe): infanteria de pueblo, con ametralladora y antitanque
VIOC_CR_fnc_team = {
	params ["_side", "_n"];
	private _t = [_side] call VIOC_CR_fnc_tag;
	private _l = ([[_t + "INFANTRY_SQ_LIGHT"]] call VIOC_CR_fnc_pool) select {_x isKindOf "Man"};
	private _mg = ([[_t + "INFANTRY_SQ_MG"]] call VIOC_CR_fnc_pool) select {_x isKindOf "Man"};
	private _at = ([[_t + "INFANTRY_SQ_AT"]] call VIOC_CR_fnc_pool) select {_x isKindOf "Man"};
	if (count _l == 0) then {
		private _s = missionNamespace getVariable [format ["CTI_%1TownSoldier", _t], ""];
		if (_s isEqualType []) then {_s = _s param [0, ""]};
		if (_s isEqualType "" && {isClass (configFile >> "CfgVehicles" >> _s)}) then {_l = [_s]};
	};
	if (count _l == 0) then {_l = _mg + _at};
	if (count _l == 0) exitWith {[]};
	private _res = [selectRandom _l];
	for "_i" from 2 to _n do {
		private _r = random 1;
		private _c = selectRandom _l;
		if ((_i == 3 || {_r < 0.15}) && {count _mg > 0}) then {_c = selectRandom _mg};
		if ((_i == 4 || {_r > 0.85}) && {count _at > 0}) then {_c = selectRandom _at};
		_res pushBack _c;
	};
	_res
};

//--- [torreta (config)] -> true si tiene un arma de verdad (como ai_transport y mission_b_rules)
VIOC_CR_fnc_hasWeapon = {
	params ["_t"];
	((getArray (_t >> "weapons")) findIf {
		private _w = toLower _x;
		((_w find "smoke") < 0) && {(_w find "flare") < 0} && {(_w find "horn") < 0} && {(_w find "designator") < 0} && {(_w find "fake") < 0}
	}) >= 0
};

//--- [clase] -> true si alguna torreta (no de pasajero) lleva arma; con cache
VIOC_CR_fnc_armed = {
	params ["_cls"];
	private _k = toLower _cls;
	private _hit = VIOC_CR_ARMED_C getOrDefault [_k, -1];
	if (_hit isEqualType true) exitWith {_hit};
	private _ok = false;
	private _tur = configFile >> "CfgVehicles" >> _cls >> "turrets";
	for "_i" from 0 to (count _tur) - 1 do {
		private _t = _tur select _i;
		if (isClass _t && {!("CargoTurret" in ([_t, true] call BIS_fnc_returnParents))}) then {
			if ([_t] call VIOC_CR_fnc_hasWeapon) then {_ok = true};
			private _sub = _t >> "turrets";
			for "_j" from 0 to (count _sub) - 1 do {
				private _s = _sub select _j;
				if (isClass _s && {[_s] call VIOC_CR_fnc_hasWeapon}) then {_ok = true};
			};
		};
	};
	VIOC_CR_ARMED_C set [_k, _ok];
	_ok
};

//--- [variable de la unidad, bando] -> true si ese bando ya puede comprarla sin investigar mas (nivel de su fabrica)
VIOC_CR_fnc_noUpg = {
	params ["_var", "_side"];
	private _d = missionNamespace getVariable [_var, []];
	if !(_d isEqualType [] && {count _d > CTI_UNIT_FACTORY}) exitWith {false};
	private _lvl = _d select CTI_UNIT_UPGRADE;
	if !(_lvl isEqualType 0) exitWith {false};
	private _k = [CTI_FACTORY_BARRACKS, CTI_FACTORY_LIGHT, CTI_FACTORY_HEAVY] find (_d select CTI_UNIT_FACTORY);
	if (_k < 0) exitWith {_lvl <= 0};
	private _ui = [CTI_UPGRADE_BARRACKS, CTI_UPGRADE_LIGHT, CTI_UPGRADE_HEAVY] select _k;
	private _ups = (_side) call CTI_CO_FNC_GetSideUpgrades;
	private _have = if (_ups isEqualType [] && {count _ups > _ui}) then {_ups select _ui} else {0};
	_lvl <= _have
};

//--- [bando, pasajeros] -> camiones sin arma con sitio: Oeste/Este de su fabrica ligera (sin investigar mas); la guerrilla
//--- de sus listas de pueblo o un Zamak civil (VIOC_CR_GUER_TRUCKS)
VIOC_CR_fnc_trucks = {
	params ["_side", "_need"];
	private _res = [];
	if (_side in [west, east]) then {
		{
			private _var = _x;
			private _d = if (_var isEqualType "") then {missionNamespace getVariable [_var, []]} else {[]};
			if (_d isEqualType [] && {count _d > CTI_UNIT_SCRIPTS}) then {
				private _sc = _d select CTI_UNIT_SCRIPTS;
				private _model = _var;
				if (_sc isEqualType [] && {count _sc > 0} && {(_sc select 0) isEqualType ""}) then {_model = _sc select 0};
				if (!(_sc isEqualType "" && {_sc != ""}) && {isClass (configFile >> "CfgVehicles" >> _model)} && {_model isKindOf "Truck_F"}
					&& {!([_model] call VIOC_CR_fnc_armed)} && {(getNumber (configFile >> "CfgVehicles" >> _model >> "transportSoldier")) >= _need}
					&& {[_var, _side] call VIOC_CR_fnc_noUpg}) then {_res pushBackUnique _model};
			};
		} forEach (missionNamespace getVariable [format ["CTI_%1_%2Units", _side, CTI_LIGHT], []]);
	} else {
		_res = ([["GUER_WHEELED_SQ_LIGHT", "GUER_WHEELED_SQ_HEAVY"]] call VIOC_CR_fnc_pool) select {
			(_x isKindOf "Truck_F") && {!([_x] call VIOC_CR_fnc_armed)} && {(getNumber (configFile >> "CfgVehicles" >> _x >> "transportSoldier")) >= _need}};
		if (count _res == 0) then {_res = VIOC_CR_GUER_TRUCKS select {isClass (configFile >> "CfgVehicles" >> _x)}};
	};
	_res
};

//--- ---------------------------------- lugares ----------------------------------
//--- [bando, sideID, centro] -> [[lugar, etiqueta], ...]: base (estructura propia mas cercana o HQ) y pueblos propios a
//--- VIOC_CR_SRC_R m, con camino por tierra hasta la capital, del mas cercano al mas lejano
VIOC_CR_fnc_sources = {
	params ["_side", "_sid", "_c"];
	private _res = [];
	if (_sid in [CTI_WEST_ID, CTI_EAST_ID]) then {
		private _st = (_side) call CTI_CO_FNC_GetSideStructures;
		private _b = objNull;
		private _bd = 1e9;
		if (!isNil "_st" && {_st isEqualType []}) then {
			{
				if (!isNil "_x" && {_x isEqualType objNull} && {!isNull _x} && {alive _x}) then {
					private _d = _x distance2D _c;
					if (_d < _bd) then {_bd = _d; _b = _x};
				};
			} forEach _st;
		};
		if (isNull _b) then {
			private _hq = (_side) call CTI_CO_FNC_GetSideHQ;
			if (!isNil "_hq" && {_hq isEqualType objNull} && {!isNull _hq} && {alive _hq}) then {_b = _hq};
		};
		if (!isNull _b) then {_res pushBack [_b call VIOC_CR_fnc_p0, "la base"]};
	};
	{
		if (!(_x isEqualTo VIOC_CR_CAP) && {(_x getVariable ["cti_town_sideID", -1]) == _sid}) then {_res pushBack [_x call VIOC_CR_fnc_p0, [_x] call VIOC_CR_fnc_tname]};
	} forEach CTI_Towns;
	private _keys = [];
	{
		private _d = (_x select 0) distance2D _c;
		if (_d >= (VIOC_CR_SRC_R select 0) && {_d <= (VIOC_CR_SRC_R select 1)}) then {_keys pushBack [_d, _forEachIndex]};
	} forEach _res;
	_keys sort true;
	private _out = [];
	{
		private _s = _res select (_x select 1);
		if (count _out < 3 && {[_s select 0, _c] call VIOC_CR_fnc_dry}) then {_out pushBack _s};
	} forEach _keys;
	_out
};

//--- [lugar de salida, clase, bando] -> lugar para el camion (en un camino cercano, sin jugadores, a la vista ni enemigos) o []
VIOC_CR_fnc_srcSpot = {
	params ["_src", "_cls", "_side"];
	private _pl = call VIOC_CR_fnc_players;
	private _pts = ((_src nearRoads VIOC_CR_SRC_ROAD) apply {_x call VIOC_CR_fnc_p0}) call CTI_CO_FNC_ArrayShuffle;
	if (count _pts > 12) then {_pts resize 12};
	_pts pushBack _src;
	private _res = [];
	{
		private _p = _x;
		if (!(surfaceIsWater _p) && {(_pl findIf {(_x distance2D _p) < VIOC_CR_PLAYER}) < 0}
			&& {([_p, VIOC_CR_ENEMY, _side] call VIOC_CR_fnc_enemiesNear) == 0} && {[_p] call VIOC_CR_fnc_unseen}) then {
			private _q = _p findEmptyPosition [0, 25, _cls];
			if (count _q > 1 && {!(surfaceIsWater _q)}) then {_res = [_q select 0, _q select 1, 0]};
		};
		if (count _res > 0) exitWith {};
	} forEach _pts;
	_res
};

//--- [centro, lugar de salida] -> punto de bajada: camino de entrada a VIOC_CR_DROP_R m del centro, del lado de la salida,
//--- primero lejos de las ultimas entradas
VIOC_CR_fnc_dropSpot = {
	params ["_c", "_from"];
	private _b0 = _c getDir _from;
	private _fresh = [];
	private _any = [];
	{
		private _ri = getRoadInfo _x;
		private _type = _ri param [0, ""];
		private _p = _x call VIOC_CR_fnc_p0;
		private _d = _p distance2D _c;
		if (_d >= (VIOC_CR_DROP_R select 0) && {_d <= (VIOC_CR_DROP_R select 1)} && {_type in ["MAIN ROAD", "ROAD", "TRACK"]}
			&& {!(_ri param [2, false])} && {!(_ri param [8, false])} && {!(surfaceIsWater _p)}) then {
			private _b = _c getDir _p;
			if (([_b, _b0] call VIOC_CR_fnc_angDiff) < VIOC_CR_DROP_ARC) then {
				_any pushBack _p;
				if ((VIOC_CR_ENTRY findIf {([_b, _x] call VIOC_CR_fnc_angDiff) < VIOC_CR_ENTRY_SEP}) < 0) then {_fresh pushBack _p};
			};
		};
	} forEach (_c nearRoads ((VIOC_CR_DROP_R select 1) + 10));
	if (count _fresh > 0) exitWith {selectRandom _fresh};
	if (count _any > 0) exitWith {selectRandom _any};
	private _q = [_c, [400, 350, 450, 300], _b0] call VIOC_CR_fnc_landPoint;
	if (count _q == 0) then {_q = _c getPos [350, _b0]};
	[_q select 0, _q select 1, 0]
};

//--- [centro, bando, sideID, clase] -> punto oculto a VIOC_CR_FOOT_R m para los que llegan a pie o []
VIOC_CR_fnc_footSpot = {
	params ["_c", "_side", "_sid", "_cls"];
	private _pl = call VIOC_CR_fnc_players;
	private _oth = CTI_Towns select {(_x getVariable ["cti_town_sideID", -1]) != _sid};
	private _hqs = (([west, east] - [_side]) apply {(_x) call CTI_CO_FNC_GetSideHQ}) select {!isNil "_x" && {_x isEqualType objNull} && {!isNull _x}};
	private _ws = worldSize;
	private _a0 = random 360;
	private _brgs = [];
	for "_i" from 0 to 11 do {_brgs pushBack ((_a0 + (_i * 30)) % 360)};
	private _fresh = _brgs select {private _b = _x; (VIOC_CR_ENTRY findIf {([_b, _x] call VIOC_CR_fnc_angDiff) < VIOC_CR_ENTRY_SEP}) < 0};
	private _res = [];
	{
		private _b = _x;
		{
			private _p = _c getPos [_x, _b];
			_p = [_p select 0, _p select 1, 0];
			if (!(surfaceIsWater _p) && {(_p select 0) > 100} && {(_p select 1) > 100} && {(_p select 0) < (_ws - 100)} && {(_p select 1) < (_ws - 100)}
				&& {(_pl findIf {(_x distance2D _p) < VIOC_CR_PLAYER}) < 0}
				&& {(_oth findIf {(_x distance2D _p) < VIOC_CR_ENEMY_TOWN}) < 0}
				&& {(_hqs findIf {(_x distance2D _p) < VIOC_CR_ENEMY_HQ}) < 0}
				&& {([_p, VIOC_CR_ENEMY, _side] call VIOC_CR_fnc_enemiesNear) == 0}
				&& {[_p, _c] call VIOC_CR_fnc_dry}
				&& {[_p] call VIOC_CR_fnc_unseen}) then {
				private _q = _p findEmptyPosition [0, 40, _cls];
				if (count _q > 1 && {!(surfaceIsWater _q)}) then {_res = [_q select 0, _q select 1, 0]};
			};
			if (count _res > 0) exitWith {};
		} forEach VIOC_CR_FOOT_R;
		if (count _res > 0) exitWith {};
	} forEach (_fresh + (_brgs - _fresh));
	_res
};

//--- [centro] -> [lugar, tipo]: posicion al azar dentro de la capital que no tiene otro grupo de refuerzo a 120 m:
//--- estaticas del pueblo sin tirador, controles de carretera (towns_capital) o un grupo de edificios
VIOC_CR_fnc_pickPoint = {
	params ["_c"];
	private _taken = (VIOC_CR_GROUPS select {(_x get "state") != "orphan"}) apply {_x get "gp"};
	private _st = [];
	private _cp = [];
	private _hs = [];
	{
		private _s = _x getVariable ["CTI_defense", objNull];
		if (!isNil "_s" && {_s isEqualType objNull} && {!isNull _s} && {alive _s} && {!alive (gunner _s)} && {(locked _s) != 2}) then {
			private _p = _s call VIOC_CR_fnc_p0;
			if ((_p distance2D _c) < 480 && {(_taken findIf {(_x distance2D _p) < 120}) < 0}) then {_st pushBack _p};
		};
	} forEach ((VIOC_CR_CAP getVariable ["cti_town_defenses", []]) select {!isNull _x});
	if (!isNil "VIOC_TC_CP" && {VIOC_TC_CP isEqualType []}) then {
		{
			if (_x isEqualType createHashMap) then {
				private _p = _x getOrDefault ["pos", []];
				if (_p isEqualType [] && {count _p > 1} && {(_taken findIf {(_x distance2D _p) < 120}) < 0}) then {_cp pushBack (_p call VIOC_CR_fnc_p0)};
			};
		} forEach VIOC_TC_CP;
	};
	for "_i" from 1 to 8 do {
		private _q = _c getPos [40 + random 260, random 360];
		_q = [_q select 0, _q select 1, 0];
		if (!(surfaceIsWater _q) && {(_taken findIf {(_x distance2D _q) < 120}) < 0}
			&& {({count (_x buildingPos -1) >= 3} count (nearestObjects [_q, ["House"], 45])) >= 2}) then {_hs pushBack _q};
	};
	private _kinds = [["estaticas", _st], ["control de carretera", _cp], ["edificios", _hs]] select {count (_x select 1) > 0};
	if (count _kinds == 0) exitWith {
		private _q = _c getPos [60 + random 120, random 360];
		[[_q select 0, _q select 1, 0], "centro"]
	};
	private _other = _kinds select {(_x select 0) != VIOC_CR_LASTKIND};
	private _k = selectRandom ([_kinds, _other] select (count _other > 0));
	VIOC_CR_LASTKIND = _k select 0;
	[selectRandom (_k select 1), _k select 0]
};

//--- ---------------------------------- refuerzos ----------------------------------
//--- [bando, clases, lugar] -> grupo nuevo (vioc_cr; cti_funds 0: la mision no borra a los que tripulan estaticas del pueblo)
VIOC_CR_fnc_makeGroup = {
	params ["_side", "_team", "_pos"];
	private _g = createGroup [_side, true];
	private _a = _team select [0, 7];
	private _b = if ((count _team) > 7) then {_team select [7, (count _team) - 7]} else {[]};
	[_a, _pos, _side, _g, false, false, true, true] call CTI_CO_FNC_CreateTeam; //--- CreateTeam crea 7 a pie por llamada
	if (count _b > 0) then {[_b, _pos, _side, _g, false, false, true, true] call CTI_CO_FNC_CreateTeam};
	if (({alive _x} count (units _g)) == 0) exitWith {deleteGroup _g; grpNull};
	_g setVariable ["vioc_cr", true];
	_g setVariable ["cti_funds", 0]; //--- Server_OperateTownDefensesUnits.sqf ("remove") solo borra tiradores de grupos sin cti_funds
	_g allowFleeing 0;
	_g setBehaviour "AWARE";
	_g setCombatMode "YELLOW";
	_g
};

VIOC_CR_fnc_newEntry = {
	params ["_g", "_side", "_sid", "_state", "_tr", "_gd", "_drop", "_home", "_gp", "_from"];
	createHashMapFromArray [["g", _g], ["side", _side], ["sid", _sid], ["state", _state], ["t0", time], ["tS", time],
		["truck", _tr], ["drv", _gd], ["drop", _drop], ["home", _home], ["gp", _gp select 0], ["kind", _gp select 1], ["from", _from],
		["lp", _home], ["lt", time], ["tO", -1], ["near", false], ["done", false], ["men0", {alive _x} count (units _g)]]
};

//--- [bando, sideID, clases, clase del camion, lugar, etiqueta, posicion] -> texto ("" si no se pudo)
VIOC_CR_fnc_spawnTruck = {
	params ["_side", "_sid", "_team", "_cls", "_spot", "_label", "_gp"];
	private _c = VIOC_CR_CAP call VIOC_CR_fnc_p0;
	private _tr = [_cls, _spot, _spot getDir _c, _sid, false, false, true, "NONE", 0] call CTI_CO_FNC_CreateVehicle;
	if (isNil "_tr" || {!(_tr isEqualType objNull)} || {isNull _tr}) exitWith {""};
	_tr setVariable ["vioc_cr", true];        //--- no se guarda (filtro en Server_SaveToProfile.sqf)
	_tr setVariable ["vioc_at_noTake", 1e10]; //--- ai_transport no lo toma
	private _seats = _tr emptyPositions "Cargo";
	if (_seats < 4) exitWith {deleteVehicle _tr; ""};
	private _tag = [_side] call VIOC_CR_fnc_tag;
	private _crew = missionNamespace getVariable [format ["CTI_%1TownSoldier", _tag], ""];
	if (_crew isEqualType []) then {_crew = _crew param [0, ""]};
	if !(_crew isEqualType "" && {isClass (configFile >> "CfgVehicles" >> _crew)}) then {_crew = _team select 0};
	private _gd = createGroup [_side, true];
	private _drv = [_crew, _gd, _spot, _sid] call CTI_CO_FNC_CreateUnit;
	if (isNil "_drv" || {!(_drv isEqualType objNull)} || {isNull _drv}) exitWith {deleteVehicle _tr; deleteGroup _gd; ""};
	_drv moveInDriver _tr;
	_gd addVehicle _tr;
	_gd setVariable ["vioc_cr", true];
	_gd allowFleeing 0;
	_team resize ((count _team) min _seats);
	private _g = [_side, _team, _spot] call VIOC_CR_fnc_makeGroup;
	if (isNull _g) exitWith {deleteVehicle _drv; deleteVehicle _tr; deleteGroup _gd; ""};
	{ _x assignAsCargo _tr; _x moveInCargo _tr } forEach (units _g);
	{ if (isNull objectParent _x) then {deleteVehicle _x} } forEach (units _g); //--- el que no cupo
	private _men = {alive _x} count (units _g);
	if (_men == 0) exitWith {deleteVehicle _drv; deleteVehicle _tr; deleteGroup _gd; ""};
	private _drop = [_c, _spot] call VIOC_CR_fnc_dropSpot;
	[_gd] call VIOC_CR_fnc_clearWp;
	_gd setBehaviour "CARELESS";
	_gd setCombatMode "BLUE";
	_gd setSpeedMode "NORMAL";
	private _w = _gd addWaypoint [_drop, 0];
	_w setWaypointType "MOVE";
	_w setWaypointCompletionRadius 25;
	VIOC_CR_ENTRY = ([_c getDir _drop] + VIOC_CR_ENTRY) select [0, 2];
	VIOC_CR_GROUPS pushBack ([_g, _side, _sid, "ride", _tr, _gd, _drop, _spot, _gp, _label] call VIOC_CR_fnc_newEntry);
	[0] call VIOC_CR_fnc_stat;
	[1] call VIOC_CR_fnc_stat;
	[3, _men] call VIOC_CR_fnc_stat;
	format ["%1 hombres en camion (%2) desde %3 (%4 m), entran por %5; posicion: %6", _men, _cls, _label, round (_spot distance2D _c),
		[_c getDir _drop] call VIOC_CR_fnc_dirName, _gp select 1]
};

//--- [bando, sideID, clases, lugar, posicion] -> texto ("" si no se pudo)
VIOC_CR_fnc_spawnFoot = {
	params ["_side", "_sid", "_team", "_spot", "_gp"];
	private _c = VIOC_CR_CAP call VIOC_CR_fnc_p0;
	private _g = [_side, _team, _spot] call VIOC_CR_fnc_makeGroup;
	if (isNull _g) exitWith {""};
	private _men = {alive _x} count (units _g);
	VIOC_CR_ENTRY = ([_c getDir _spot] + VIOC_CR_ENTRY) select [0, 2];
	private _e = [_g, _side, _sid, "walk", objNull, grpNull, _spot, _spot, _gp, "a pie"] call VIOC_CR_fnc_newEntry;
	VIOC_CR_GROUPS pushBack _e;
	[_e] call VIOC_CR_fnc_goWalk;
	[0] call VIOC_CR_fnc_stat;
	[2] call VIOC_CR_fnc_stat;
	[3, _men] call VIOC_CR_fnc_stat;
	format ["%1 hombres a pie desde %2 m por %3; posicion: %4", _men, round (_spot distance2D _c), [_c getDir _spot] call VIOC_CR_fnc_dirName, _gp select 1]
};

//--- [capital, sideID] -> "" o por que se espera (mision B: la guarnicion de BECTI la mantiene vioc_mb_hold)
VIOC_CR_fnc_mbWait = {
	params ["_cap", "_sid"];
	if (_sid != CTI_WEST_ID || {!(_cap getVariable ["vioc_mb_key", false])}) exitWith {""};
	private _hold = _cap getVariable ["vioc_mb_hold", -1];
	if (!(_hold isEqualType 0) || {_hold <= time}) exitWith {""};
	private _made = _cap getVariable ["vioc_mb_made", -1];
	if !(_made isEqualType 0) then {_made = -1};
	if (!(_cap getVariable ["cti_town_occupation_active", false]) || {_made < 0} || {(time - _made) < 120}) exitWith {
		"mision B: la guarnicion del gobierno esta presente o se esta rehaciendo (vioc_mb_hold); sin refuerzos"
	};
	""
};

//--- [forzado] -> [mando un grupo, texto, reintentar pronto]
VIOC_CR_fnc_dispatch = {
	params [["_forced", false]];
	private _cap = VIOC_CR_CAP;
	private _sid = _cap getVariable ["cti_town_sideID", -1];
	if !(_sid in [CTI_WEST_ID, CTI_EAST_ID, CTI_RESISTANCE_ID]) exitWith {[false, "la capital no tiene duenio", false]};
	private _side = (_sid) call CTI_CO_FNC_GetSideFromID;
	private _c = _cap call VIOC_CR_fnc_p0;
	private _mine = VIOC_CR_GROUPS select {((_x get "side") isEqualTo _side) && {(_x get "state") != "orphan"}};
	private _men = 0;
	private _transit = 0;
	{
		private _us = (units (_x get "g")) select {alive _x};
		_men = _men + (count _us);
		_transit = _transit + ({(_x distance2D _c) >= VIOC_CR_RANGE} count _us);
	} forEach _mine;
	private _nG = {({alive _x} count (units (_x get "g"))) >= 2} count _mine;
	if (_nG >= VIOC_CR_MAXG) exitWith {[false, format ["tope de grupos de refuerzo (%1)", VIOC_CR_MAXG], false]};
	if (({({alive _x} count (units (_x get "g"))) >= 2} count VIOC_CR_GROUPS) >= (2 * VIOC_CR_MAXG)) exitWith {[false, "tope de grupos (con los que quedan de un duenio anterior)", false]};
	private _def = [_side] call VIOC_CR_fnc_defenders;
	if (!_forced && {(_def + _transit) >= VIOC_CR_MIN}) exitWith {[false, format ["%1 defensores a %2 m y %3 en camino (minimo %4)", _def, VIOC_CR_RANGE, _transit, VIOC_CR_MIN], false]};
	private _mb = [_cap, _sid] call VIOC_CR_fnc_mbWait;
	if (!_forced && {_mb != ""}) exitWith {[false, _mb, false]};
	private _n = (VIOC_CR_SIZE select 0) + floor (random (((VIOC_CR_SIZE select 1) - (VIOC_CR_SIZE select 0)) + 1));
	_n = _n min ((VIOC_CR_MAXG * VIOC_CR_MEN_GROUP) - _men);
	if (_n < 4) exitWith {[false, format ["tope de hombres de refuerzo (%1 vivos)", _men], false]};
	private _room = call VIOC_CR_fnc_room;
	if (_room < (_n + 1)) exitWith {[false, format ["sin presupuesto de IA (%1 plazas libres)", _room], true]};
	[_n + 1] call VIOC_CR_fnc_reserve; //--- reserva antes de crear (las creaciones tienen pausas); si al final no sale, sobra hasta el proximo recuento de perf_cleanup
	private _team = [_side, _n] call VIOC_CR_fnc_team;
	if (count _team == 0) exitWith {[false, "sin infanteria de pueblo para ese bando", false]};
	private _gp = [_c] call VIOC_CR_fnc_pickPoint;
	private _done = "";
	private _trs = [_side, VIOC_CR_SIZE select 0] call VIOC_CR_fnc_trucks; //--- el grupo se ajusta a los asientos del camion
	if (count _trs > 0) then {
		{
			_x params ["_sp", "_label"];
			if (_done == "") then {
				private _cls = selectRandom _trs;
				private _spot = [_sp, _cls, _side] call VIOC_CR_fnc_srcSpot;
				if (count _spot > 0) then {_done = [_side, _sid, +_team, _cls, _spot, _label, _gp] call VIOC_CR_fnc_spawnTruck};
			};
		} forEach ([_side, _sid, _c] call VIOC_CR_fnc_sources);
	};
	if (_done == "") then {
		private _spot = [_c, _side, _sid, _team select 0] call VIOC_CR_fnc_footSpot;
		if (count _spot > 0) then {_done = [_side, _sid, _team, _spot, _gp] call VIOC_CR_fnc_spawnFoot};
	};
	if (_done == "") exitWith {[false, "sin lugar oculto ni camion para los refuerzos", true]};
	private _last = VIOC_CR_GROUPS select ((count VIOC_CR_GROUPS) - 1);
	private _how = if ((_last get "state") == "ride") then {format ["en camion desde %1", _last get "from"]} else {"a pie"};
	[_side, format ["Refuerzos en camino a %1 (%2).", [_cap] call VIOC_CR_fnc_tname, _how]] call VIOC_CR_fnc_say;
	[true, format ["%1 para %2: %3", [_side] call VIOC_CR_fnc_sideName, [_cap] call VIOC_CR_fnc_tname, _done], false]
};

//--- [entrada]: a pie hasta su posicion
VIOC_CR_fnc_goWalk = {
	params ["_e"];
	private _g = _e get "g";
	private _l = leader _g;
	[_g] call VIOC_CR_fnc_clearWp;
	{
		if (alive _x && {!isPlayer _x}) then {
			_x enableAI "PATH";
			_x setUnitPos "AUTO";
			if (!(_x isEqualTo _l) && {isNull objectParent _x}) then {_x doFollow _l};
		};
	} forEach (units _g);
	_g setBehaviour "AWARE";
	_g setCombatMode "YELLOW";
	_g setSpeedMode (["NORMAL", "FULL"] select ((_l distance2D (_e get "gp")) > 400));
	private _w = _g addWaypoint [_e get "gp", 0];
	_w setWaypointType "MOVE";
	_w setWaypointCompletionRadius 30;
	_e set ["state", "walk"];
	_e set ["tS", time];
};

//--- [grupo, posicion]: sin LAMBS, estaticas vacias (2 como mucho) y posiciones de edificios a mano
VIOC_CR_fnc_garrisonVanilla = {
	params ["_g", "_gp"];
	private _l = leader _g;
	private _us = (units _g) select {alive _x && {isNull objectParent _x} && {!(_x isEqualTo _l)}};
	private _sts = (_gp nearEntities [["StaticWeapon"], VIOC_CR_GARRISON_R]) select {alive _x && {(_x emptyPositions "Gunner") > 0} && {(locked _x) != 2}};
	{
		if (count _us > 2) then {
			private _u = _us deleteAt 0;
			_u assignAsGunner _x;
			[_u] orderGetIn true;
		};
	} forEach (_sts select [0, 2]);
	private _hp = [];
	{ _hp append (_x buildingPos -1) } forEach ((nearestObjects [_gp, ["House"], VIOC_CR_GARRISON_R]) select {alive _x});
	_hp = _hp call CTI_CO_FNC_ArrayShuffle;
	{
		if (_forEachIndex < (count _hp)) then {_x doMove (_hp select _forEachIndex)};
	} forEach _us;
	private _w = _g addWaypoint [_gp, 0];
	_w setWaypointType "HOLD";
};

//--- [entrada]: en posicion (LAMBS taskGarrison si esta cargado: edificios y estaticas vacias a VIOC_CR_GARRISON_R m)
VIOC_CR_fnc_garrison = {
	params ["_e"];
	private _g = _e get "g";
	private _gp = _e get "gp";
	[_g] call VIOC_CR_fnc_clearWp;
	_g setSpeedMode "NORMAL";
	if (!isNil "lambs_wp_fnc_taskGarrison") then {
		[_g, _gp, VIOC_CR_GARRISON_R, [], false, (random 1) < 0.5, -2, false] call lambs_wp_fnc_taskGarrison;
	} else {
		[_g, _gp] call VIOC_CR_fnc_garrisonVanilla;
	};
	_g setCombatMode "YELLOW";
	_e set ["state", "hold"];
	_e set ["tS", time];
	[format ["grupo %1 en posicion (%2) a %3 m del centro de %4", groupId _g, _e get "kind", round (_gp distance2D VIOC_CR_CAP), [VIOC_CR_CAP] call VIOC_CR_fnc_tname]] call VIOC_CR_fnc_log;
};

//--- [entrada, motivo]: la gente baja del camion; el camion queda en VIOC_CR_TRUCKS (vuelve y se borra)
VIOC_CR_fnc_unload = {
	params ["_e", "_why"];
	private _tr = _e get "truck";
	private _g = _e get "g";
	private _in = if (isNull _g) then {[]} else {(units _g) select {alive _x && {!isNull objectParent _x}}};
	{ unassignVehicle _x } forEach _in;
	if (count _in > 0) then {_in orderGetIn false};
	if (!isNull _tr && {!isNull _g}) then {_g leaveVehicle _tr};
	if (!isNull _tr && {alive _tr} && {!isNull _g}) then {
		private _d = driver _tr;
		if (!isNull _d && {alive _d}) then {doStop _d};
	};
	if (!isNull _tr || {!isNull (_e get "drv")}) then {
		VIOC_CR_TRUCKS pushBack (createHashMapFromArray [["v", _tr], ["g", _e get "drv"], ["t", time], ["home", _e get "home"], ["sent", false], ["cargo", _g], ["done", false]]);
	};
	_e set ["truck", objNull];
	_e set ["drv", grpNull];
	[format ["grupo %1 baja del camion (%2) a %3 m del centro", groupId _g, _why, round ((leader _g) distance2D VIOC_CR_CAP)]] call VIOC_CR_fnc_log;
	if (((_e get "state") == "orphan") || {isNull _g}) exitWith {};
	//--- camion atascado, roto o lento todavia lejos (a mas de 2 km) y sin jugadores cerca: desisten (se borran) y se reintenta pronto
	private _us = (units _g) select {alive _x};
	if ((_why in ["atascado", "tiempo", "camion perdido", "sin conductor"]) && {((leader _g) distance2D VIOC_CR_CAP) > 2000} && {[_us, VIOC_CR_FREE] call VIOC_CR_fnc_farFromPlayers}) exitWith {
		{ deleteVehicle _x } forEach _us;
		_e set ["done", true];
		VIOC_CR_NEXT = VIOC_CR_NEXT min (time + VIOC_CR_RETRY);
		[4] call VIOC_CR_fnc_stat;
		[format ["grupo %1 desiste lejos de la capital (%2): borrado sin jugadores cerca; nueva revision en %3 s", groupId _g, _why, round (VIOC_CR_NEXT - time)]] call VIOC_CR_fnc_log;
	};
	[_e] call VIOC_CR_fnc_goWalk;
	if (_why == "contacto") then {_g setCombatMode "RED"};
};

//--- [entrada]: en camion hacia la entrada
VIOC_CR_fnc_rideTick = {
	params ["_e"];
	private _tr = _e get "truck";
	private _why = "";
	if (isNull _tr || {!alive _tr} || {!canMove _tr}) then {_why = "camion perdido"};
	if (_why == "" && {isNull (driver _tr) || {!alive (driver _tr)}}) then {_why = "sin conductor"};
	if (_why == "" && {(_tr distance2D (_e get "drop")) < VIOC_CR_ARRIVE}) then {_why = "llegada"};
	if (_why == "" && {([getPosATL _tr, VIOC_CR_CONTACT, _e get "side"] call VIOC_CR_fnc_enemiesNear) > 0}) then {_why = "contacto"};
	if (_why == "" && {(time - (_e get "t0")) > VIOC_CR_RIDE_MAX}) then {_why = "tiempo"};
	if (_why == "" && {(time - (_e get "lt")) >= VIOC_CR_STUCK}) then {
		if (((getPosATL _tr) distance2D (_e get "lp")) < 20) then {_why = "atascado"} else {_e set ["lp", (getPosATL _tr) call VIOC_CR_fnc_p0]; _e set ["lt", time]};
	};
	if (_why != "") then {[_e, _why] call VIOC_CR_fnc_unload};
};

//--- [entrada]: una pasada por grupo de refuerzo
VIOC_CR_fnc_groupTick = {
	params ["_e"];
	private _g = _e get "g";
	private _alive = if (isNull _g) then {[]} else {(units _g) select {alive _x}};
	if (count _alive == 0) exitWith {
		if ((_e get "state") == "ride") then {_e set ["state", "orphan"]; [_e, "sin gente"] call VIOC_CR_fnc_unload}; //--- el camion queda para volver y borrarse
		_e set ["done", true];
	};
	private _c = VIOC_CR_CAP call VIOC_CR_fnc_p0;
	private _st = _e get "state";
	//--- la capital cambio de duenio: siguen peleando donde esten; se borran despues lejos de jugadores
	if ((VIOC_CR_CAP getVariable ["cti_town_sideID", -1]) != (_e get "sid")) then {
		if (_st != "orphan") then {
			if (_st == "ride") then {_e set ["state", "orphan"]; [_e, "capital perdida"] call VIOC_CR_fnc_unload};
			_e set ["state", "orphan"];
			_e set ["tO", time];
			_st = "orphan";
			[format ["grupo %1 (%2): %3 cambio de duenio, siguen peleando y se borran despues lejos de jugadores", groupId _g, _e get "side", [VIOC_CR_CAP] call VIOC_CR_fnc_tname]] call VIOC_CR_fnc_log;
		};
	} else {
		if (_st == "orphan") then {[_e] call VIOC_CR_fnc_goWalk; _st = "walk"}; //--- la recupero su bando: vuelven a su posicion
	};
	if (((leader _g) distance2D _c) < VIOC_CR_RANGE) then {_e set ["near", true]};
	switch (_st) do {
		case "ride": {[_e] call VIOC_CR_fnc_rideTick};
		case "walk": {
			private _l = leader _g;
			private _d = _l distance2D (_e get "gp");
			if ((_d < VIOC_CR_ARRIVE) || {(_d < 200) && {unitReady _l}} || {(time - (_e get "tS")) > VIOC_CR_WALK_MAX}) then {[_e] call VIOC_CR_fnc_garrison};
		};
		case "hold": {
			if ((time - (_e get "tS")) > 300 && {((leader _g) distance2D _c) > VIOC_CR_STRAY} && {([_e get "side"] call VIOC_CR_fnc_threat) < VIOC_CR_THREAT_MIN}) then {[_e] call VIOC_CR_fnc_goWalk};
		};
		case "orphan": {
			if ((time - (_e get "tO")) > VIOC_CR_ORPHAN_DELAY && {[_alive, VIOC_CR_FREE] call VIOC_CR_fnc_farFromPlayers}) then {
				{ deleteVehicle _x } forEach _alive;
				deleteGroup _g;
				_e set ["done", true];
				[4] call VIOC_CR_fnc_stat;
				[format ["grupo de refuerzo de %1 sin capital borrado (%2 hombres, sin jugadores a %3 m)", _e get "side", count _alive, VIOC_CR_FREE]] call VIOC_CR_fnc_log;
			};
		};
	};
	//--- perdidos: nunca llegaron cerca de la capital
	if (!(_e get "done") && {!(_e get "near")} && {(_e get "state") in ["walk", "hold"]} && {(time - (_e get "t0")) > VIOC_CR_LOST} && {[_alive, VIOC_CR_FREE] call VIOC_CR_fnc_farFromPlayers}) then {
		{ deleteVehicle _x } forEach _alive;
		deleteGroup _g;
		_e set ["done", true];
		[4] call VIOC_CR_fnc_stat;
		[format ["grupo de refuerzo de %1 que no llego a la capital en %2 s borrado (%3 hombres)", _e get "side", VIOC_CR_LOST, count _alive]] call VIOC_CR_fnc_log;
	};
};

//--- Camiones que ya dejaron su carga: los que siguen dentro salen, el camion vuelve y se borra lejos de jugadores
VIOC_CR_fnc_trucksTick = {
	private _pl = call VIOC_CR_fnc_players;
	{
		private _r = _x;
		private _v = _r get "v";
		private _gd = _r get "g";
		private _cg = _r get "cargo";
		private _age = time - (_r get "t");
		private _vOk = !isNull _v && {alive _v};
		if (_vOk && {((crew _v) findIf {isPlayer _x}) >= 0}) then {
			//--- un jugador lo tomo: es suyo (se puede guardar y lo trata perf_cleanup)
			_v setVariable ["vioc_cr", nil];
			_v setVariable ["vioc_at_noTake", nil];
			_r set ["done", true];
		} else {
			if (_vOk && {_age > 25} && {!isNull _cg}) then {
				{ if (((objectParent _x) isEqualTo _v) && {(speed _v) < 3}) then {moveOut _x} } forEach (units _cg);
			};
			private _left = isNull _cg || {!_vOk} || {((units _cg) findIf {(objectParent _x) isEqualTo _v}) < 0};
			if (!(_r get "sent") && {_left || {_age > 45}}) then {
				_r set ["sent", true];
				if (_vOk && {!isNull _gd}) then {
					[_gd] call VIOC_CR_fnc_clearWp;
					private _d = driver _v;
					if (!isNull _d && {alive _d}) then {_d doMove (_r get "home")};
				};
			};
			private _crew = if (isNull _gd) then {[]} else {(units _gd) select {alive _x}};
			private _objs = _crew + (if (_vOk) then {[_v]} else {[]});
			private _freeR = [VIOC_CR_TRUCK_FREE, 150] select (_age > VIOC_CR_TRUCK_MAXT);
			if (_left && {_age > 30} && {(_objs findIf {private _o = _x; (_pl findIf {(_x distance2D _o) < _freeR}) >= 0}) < 0}) then {
				private _others = _vOk && {((crew _v) findIf {alive _x && {!(_x in _crew)}}) >= 0};
				{ if (!isPlayer _x) then {deleteVehicle _x} } forEach _crew;
				if (_vOk && {!_others}) then {deleteVehicle _v};
				if (!isNull _gd && {({alive _x} count (units _gd)) == 0}) then {deleteGroup _gd};
				_r set ["done", true];
				[5] call VIOC_CR_fnc_stat;
			};
		};
	} forEach VIOC_CR_TRUCKS;
	VIOC_CR_TRUCKS = VIOC_CR_TRUCKS select {!(_x get "done")};
};

//--- ---------------------------------- prioridad para la IA ----------------------------------
//--- [grupo, bando, comandante, ordenes validas] -> true si la escuadra IA puede ir (las mismas reglas que ai_tactics)
VIOC_CR_fnc_teamOk = {
	params ["_g", "_side", "_cmd", "_orders"];
	if (isNull _g || {_g isEqualTo _cmd}) exitWith {false};
	private _l = leader _g;
	if (isNull _l || {!alive _l} || {isPlayer _l} || {!local _l}) exitWith {false};
	if (((units _g) findIf {isPlayer _x}) >= 0) exitWith {false};
	if !(_g getVariable ["cti_aifsm_handled", false]) exitWith {false};
	if (!isNil {_g getVariable "vioc_tac_man"} || {_g getVariable ["vioc_tac_busy", false]} || {!isNil {_g getVariable "vioc_cr_role"}}) exitWith {false};
	if ((_g getVariable ["vioc_air_busy", false]) || {_g getVariable ["vioc_af_scramble", false]} || {_g getVariable ["vioc_specops", false]} || {!isNil {_g getVariable "vioc_at_owner"}}) exitWith {false};
	if ((_g getVariable ["cti_nextrespawn", -1]) > time) exitWith {false};
	if ((_g getVariable ["cti_role", ""]) in (missionNamespace getVariable [format ["CTI_SQUADS_%1_KIND_AIR", _side], []])) exitWith {false};
	private _v = objectParent _l;
	if (!isNull _v && {(_v isKindOf "Air") || {_v isKindOf "Ship"}}) exitWith {false};
	if (({alive _x} count (units _g)) < 3) exitWith {false};
	(_g getVariable ["cti_order", -1]) in _orders
};

//--- [bando, centro, cuantas, alcance, tipo ("def" o "atk")] -> escuadras mas cercanas que pueden ir
VIOC_CR_fnc_pickTeams = {
	params ["_side", "_c", "_n", "_range", "_kind"];
	if (_n < 1) exitWith {[]};
	private _cmd = [_side] call VIOC_CR_fnc_cmd;
	private _human = !isNull _cmd && {isPlayer (leader _cmd)};
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	private _take = [CTI_ORDER_TAKETOWN, CTI_ORDER_TAKETOWN_AUTO, CTI_ORDER_TAKEHOLDTOWN, CTI_ORDER_TAKEHOLDTOWN_AUTO];
	private _auto = [CTI_ORDER_TAKETOWNS, CTI_ORDER_TAKETOWN_AUTO, CTI_ORDER_TAKEHOLDTOWNS, CTI_ORDER_TAKEHOLDTOWN_AUTO];
	private _orders = _auto;
	if (_kind == "def") then {
		_orders = _auto + [CTI_ORDER_HOLDTOWNSBASES];
		if (!_human) then {_orders = _orders + [CTI_ORDER_TAKETOWN, CTI_ORDER_TAKEHOLDTOWN, CTI_ORDER_HOLDTOWNSBASE]};
	};
	private _gs = (_side) call CTI_CO_FNC_GetSideGroups;
	if (_kind == "atk") then {
		private _air = missionNamespace getVariable [format ["CTI_SQUADS_%1_KIND_AIR", _side], []];
		private _ground = _gs select {!isNull _x && {!(_x isEqualTo _cmd)} && {!isPlayer (leader _x)} && {!((_x getVariable ["cti_role", ""]) in _air)}};
		_n = _n min (floor (VIOC_CR_ATK_SHARE * (count _ground)));
	};
	if (_n < 1) exitWith {[]};
	private _keys = [];
	{
		private _g = _x;
		if ([_g, _side, _cmd, _orders] call VIOC_CR_fnc_teamOk) then {
			private _l = leader _g;
			private _lp = getPosATL (vehicle _l);
			private _d = _lp distance2D _c;
			private _o = _g getVariable ["cti_order", -1];
			private _p = _g getVariable ["cti_order_pos", objNull];
			private _already = _p isEqualTo VIOC_CR_CAP;
			//--- no se saca a una escuadra que esta por tomar otro pueblo (a menos de 700 m de el)
			private _near = (_o in _take) && {_p isEqualType objNull} && {!isNull _p} && {!_already} && {(_p getVariable ["cti_town_sideID", -1]) != _sid} && {(_lp distance2D _p) < 700};
			if (_d < _range && {!_already} && {!_near} && {!([_l, 300] call VIOC_CR_fnc_inCombat)} && {[_lp, _c] call VIOC_CR_fnc_dry}) then {
				_keys pushBack [_d + ([0, VIOC_CR_HOLD_PENALTY] select (_o in [CTI_ORDER_HOLDTOWNSBASES, CTI_ORDER_HOLDTOWNSBASE])), _forEachIndex];
			};
		};
	} forEach _gs;
	_keys sort true;
	(_keys select [0, _n]) apply {_gs select (_x select 1)}
};

//--- [grupo, orden, posicion]: orden de la mision de una vez (semilla nueva para cortar el hilo anterior y cti_team_reload
//--- para que no se mande el mensaje de "nueva orden"), como ai_tactics
VIOC_CR_fnc_setOrder = {
	params ["_g", "_order", "_pos"];
	isNil {
		_g setVariable ["cti_order_seed", time + random 100000];
		_g setVariable ["cti_team_reload", true];
		_g setVariable ["cti_order_pos", _pos, true];
		_g setVariable ["cti_order", _order, true];
	};
};

//--- [grupo, orden original, posicion original, ordenes de este parche] -> true si devolvio la orden (solo si sigue siendo la
//--- de este parche sobre la capital y ai_tactics no lo tiene en una maniobra); las automaticas, para que la mision elija de nuevo
VIOC_CR_fnc_restore = {
	params ["_g", "_o", "_p", "_mine"];
	if (isNull _g || {!isNil {_g getVariable "vioc_tac_man"}}) exitWith {false};
	if (!((_g getVariable ["cti_order", -1]) in _mine) || {!((_g getVariable ["cti_order_pos", objNull]) isEqualTo VIOC_CR_CAP)}) exitWith {false};
	if (_o in [CTI_ORDER_TAKETOWNS, CTI_ORDER_TAKETOWN_AUTO]) then {_o = CTI_ORDER_TAKETOWNS; _p = [0, 0]};
	if (_o in [CTI_ORDER_TAKEHOLDTOWNS, CTI_ORDER_TAKEHOLDTOWN_AUTO]) then {_o = CTI_ORDER_TAKEHOLDTOWNS; _p = [0, 0]};
	if (_o == CTI_ORDER_HOLDTOWNSBASES) then {_p = [0, 0]};
	if (_o in [CTI_ORDER_TAKETOWN, CTI_ORDER_TAKEHOLDTOWN, CTI_ORDER_HOLDTOWNSBASE] && {!(_p isEqualType objNull) || {isNull _p} || {_p isEqualTo VIOC_CR_CAP}}) then {
		_o = switch (_o) do {case CTI_ORDER_TAKETOWN: {CTI_ORDER_TAKETOWNS}; case CTI_ORDER_TAKEHOLDTOWN: {CTI_ORDER_TAKEHOLDTOWNS}; default {CTI_ORDER_HOLDTOWNSBASES}};
		_p = [0, 0];
	};
	if !(_o in [CTI_ORDER_TAKETOWNS, CTI_ORDER_TAKETOWN, CTI_ORDER_TAKETOWN_AUTO, CTI_ORDER_TAKEHOLDTOWNS, CTI_ORDER_TAKEHOLDTOWN, CTI_ORDER_TAKEHOLDTOWN_AUTO,
		CTI_ORDER_HOLDTOWNSBASES, CTI_ORDER_HOLDTOWNSBASE, CTI_ORDER_MOVE]) then {_o = CTI_ORDER_TAKETOWNS; _p = [0, 0]};
	[_g, _o, _p] call VIOC_CR_fnc_setOrder;
	true
};

//--- [bando, forzado] -> texto: el duenio manda una escuadra a defender la capital
VIOC_CR_fnc_defLaunch = {
	params ["_side", ["_forced", false]];
	private _c = VIOC_CR_CAP call VIOC_CR_fnc_p0;
	private _teams = [_side, _c, VIOC_CR_DEF_TEAMS, VIOC_CR_DEF_RANGE, "def"] call VIOC_CR_fnc_pickTeams;
	VIOC_CR_DEF_NEXT set [str _side, time + ([60, VIOC_CR_DEF_COOLDOWN] select (count _teams > 0))];
	if (count _teams == 0) exitWith {format ["%1 no tiene escuadras libres a menos de %2 m (por tierra, sin combate cerca)", _side, VIOC_CR_DEF_RANGE]};
	{
		private _g = _x;
		VIOC_CR_DEF pushBack (createHashMapFromArray [["g", _g], ["side", _side], ["order", _g getVariable ["cti_order", CTI_ORDER_TAKETOWNS]],
			["pos", _g getVariable ["cti_order_pos", [0, 0]]], ["t0", time], ["calm", -1], ["done", false]]);
		_g setVariable ["vioc_cr_role", "def"];
		[_g, CTI_ORDER_HOLDTOWNSBASE, VIOC_CR_CAP] call VIOC_CR_fnc_setOrder;
		[6] call VIOC_CR_fnc_stat;
	} forEach _teams;
	private _tn = [VIOC_CR_CAP] call VIOC_CR_fnc_tname;
	[_side, format ["[Capital] %1 a defender %2.", if (count _teams == 1) then {"Una escuadra va"} else {format ["%1 escuadras van", count _teams]}, _tn]] call VIOC_CR_fnc_say;
	format ["%1 manda %2 a defender %3%4", _side, (_teams apply {groupId _x}) joinString ", ", _tn, ["", " (forzado)"] select _forced]
};

//--- [entrada, sideID duenio]: seguimiento de una escuadra que defiende la capital
VIOC_CR_fnc_defTrack = {
	params ["_e", "_own"];
	private _g = _e get "g";
	private _side = _e get "side";
	//--- diezmada: primero se espera a que ai_tactics la suelte; despues vuelve a su orden (si no, BECTI la mantiene para siempre)
	if (!isNull _g && {!isNil {_g getVariable "vioc_tac_man"}} && {(time - (_e get "t0")) < (VIOC_CR_DEF_MAXT + 1800)}) exitWith {};
	if (isNull _g || {({alive _x} count (units _g)) < 2}) exitWith {
		if (!isNull _g) then {
			[_g, _e get "order", _e get "pos", [CTI_ORDER_HOLDTOWNSBASE]] call VIOC_CR_fnc_restore;
			_g setVariable ["vioc_cr_role", nil];
		};
		_e set ["done", true];
	};
	//--- ai_tactics la tiene en una maniobra (pinza o contraataque): se espera a que la suelte (le devuelve esta orden)
	if (!isNil {_g getVariable "vioc_tac_man"} && {(time - (_e get "t0")) < (VIOC_CR_DEF_MAXT + 1800)}) exitWith {};
	private _mine = ((_g getVariable ["cti_order", -1]) isEqualTo CTI_ORDER_HOLDTOWNSBASE) && {(_g getVariable ["cti_order_pos", objNull]) isEqualTo VIOC_CR_CAP};
	private _end = "";
	if (_own != ((_side) call CTI_CO_FNC_GetSideID)) then {_end = "capital perdida"};
	if (_end == "" && {!_mine}) then {
		//--- el comandante IA reparte sus defensores cada 10 min (Update_Orders): mientras dure la amenaza vuelve a la capital
		private _cmd = [_side] call VIOC_CR_fnc_cmd;
		if (((_g getVariable ["cti_order", -1]) isEqualTo CTI_ORDER_HOLDTOWNSBASE) && {isNull _cmd || {!isPlayer (leader _cmd)}} && {!isPlayer (leader _g)}) then {
			[_g, CTI_ORDER_HOLDTOWNSBASE, VIOC_CR_CAP] call VIOC_CR_fnc_setOrder;
		} else {
			_end = "orden cambiada";
		};
	};
	if (_end == "" && {(time - (_e get "t0")) > VIOC_CR_DEF_MAXT}) then {_end = "tiempo"};
	if (_end == "") then {
		if (([_side] call VIOC_CR_fnc_threat) >= VIOC_CR_THREAT_MIN) then {_e set ["calm", -1]} else {
			if ((_e get "calm") < 0) then {_e set ["calm", time]};
			if ((time - (_e get "calm")) > VIOC_CR_DEF_CALM) then {_end = "sin amenaza"};
		};
	};
	if (_end != "") then {
		private _back = [_g, _e get "order", _e get "pos", [CTI_ORDER_HOLDTOWNSBASE]] call VIOC_CR_fnc_restore;
		_g setVariable ["vioc_cr_role", nil];
		_e set ["done", true];
		[format ["defensa de %1 por %2 (%3) termina: %4; orden devuelta %5", [VIOC_CR_CAP] call VIOC_CR_fnc_tname, groupId _g, _side, _end, _back]] call VIOC_CR_fnc_log;
	};
};

VIOC_CR_fnc_defTick = {
	private _own = VIOC_CR_CAP getVariable ["cti_town_sideID", -1];
	{ [_x, _own] call VIOC_CR_fnc_defTrack } forEach (VIOC_CR_DEF + []); //--- copia superficial: los mismos hashmaps
	VIOC_CR_DEF = VIOC_CR_DEF select {!(_x get "done")};
	if (VIOC_CR_PRIO < 1 || {!(_own in [CTI_WEST_ID, CTI_EAST_ID])}) exitWith {};
	private _side = (_own) call CTI_CO_FNC_GetSideFromID;
	private _thr = [_side] call VIOC_CR_fnc_threat;
	VIOC_CR_THREAT = [_side, _thr, time];
	if (_thr < VIOC_CR_THREAT_MIN) exitWith {};
	if (({(_x get "side") isEqualTo _side} count VIOC_CR_DEF) >= VIOC_CR_DEF_TEAMS) exitWith {};
	if (time < (VIOC_CR_DEF_NEXT getOrDefault [str _side, -1])) exitWith {};
	[format ["amenaza sobre %1: %2 enemigos a %3 m; %4", [VIOC_CR_CAP] call VIOC_CR_fnc_tname, _thr, VIOC_CR_THREAT_R, [_side] call VIOC_CR_fnc_defLaunch]] call VIOC_CR_fnc_log;
};

//--- [bando, forzado] -> texto: el bando que no tiene la capital manda escuadras libres a tomarla
VIOC_CR_fnc_atkLaunch = {
	params ["_side", ["_forced", false]];
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	private _own = VIOC_CR_CAP getVariable ["cti_town_sideID", -1];
	private _tn = [VIOC_CR_CAP] call VIOC_CR_fnc_tname;
	if (_own == _sid) exitWith {format ["%1 ya es de %2", _tn, _side]};
	//--- ai_tactics ya tiene una maniobra o un contraataque pendiente de ese bando sobre la capital: no se duplica
	if (!isNil "VIOC_TAC_MAN" && {VIOC_TAC_MAN isEqualType []} && {(VIOC_TAC_MAN findIf {(_x isEqualType createHashMap) && {(_x getOrDefault ["side", sideUnknown]) isEqualTo _side} && {(_x getOrDefault ["town", objNull]) isEqualTo VIOC_CR_CAP}}) >= 0}) exitWith {
		format ["%1: ai_tactics ya maniobra sobre %2", _side, _tn]
	};
	if (!isNil "VIOC_TAC_REQ" && {VIOC_TAC_REQ isEqualType []} && {(VIOC_TAC_REQ findIf {(_x isEqualType createHashMap) && {!(_x getOrDefault ["done", false])} && {(_x getOrDefault ["side", sideUnknown]) isEqualTo _side} && {(_x getOrDefault ["town", objNull]) isEqualTo VIOC_CR_CAP}}) >= 0}) exitWith {
		format ["%1: ai_tactics tiene un contraataque pendiente sobre %2", _side, _tn]
	};
	if (({(_x get "side") isEqualTo _side} count VIOC_CR_ATK) > 0) exitWith {format ["%1: ya hay un ataque prioritario en curso", _side]};
	private _take = [CTI_ORDER_TAKETOWN, CTI_ORDER_TAKETOWN_AUTO, CTI_ORDER_TAKEHOLDTOWN, CTI_ORDER_TAKEHOLDTOWN_AUTO];
	private _going = {!isNull _x && {(_x getVariable ["cti_order_pos", objNull]) isEqualTo VIOC_CR_CAP} && {(_x getVariable ["cti_order", -1]) in _take}} count ((_side) call CTI_CO_FNC_GetSideGroups);
	if (_going >= VIOC_CR_ATK_TEAMS) exitWith {format ["%1: ya van %2 escuadras hacia %3", _side, _going, _tn]};
	private _c = VIOC_CR_CAP call VIOC_CR_fnc_p0;
	private _teams = [_side, _c, VIOC_CR_ATK_TEAMS - _going, VIOC_CR_ATK_RANGE, "atk"] call VIOC_CR_fnc_pickTeams;
	if (count _teams == 0) exitWith {format ["%1: sin escuadras libres a menos de %2 m", _side, VIOC_CR_ATK_RANGE]};
	private _def = if (_own in [CTI_WEST_ID, CTI_EAST_ID, CTI_RESISTANCE_ID]) then {[(_own) call CTI_CO_FNC_GetSideFromID] call VIOC_CR_fnc_defenders} else {0};
	private _men = 0;
	{ _men = _men + ({alive _x} count (units _x)) } forEach _teams;
	if (!_forced && {((count _teams) + _going) < 2} && {_def >= 10}) exitWith {format ["%1: una sola escuadra libre contra %2 defensores, se espera", _side, _def]};
	if (!_forced && {_men < (0.5 * _def)}) exitWith {format ["%1: pocas fuerzas (%2 hombres contra %3 defensores), se espera", _side, _men, _def]};
	{
		private _g = _x;
		private _o = _g getVariable ["cti_order", CTI_ORDER_TAKETOWNS];
		VIOC_CR_ATK pushBack (createHashMapFromArray [["g", _g], ["side", _side], ["order", _o], ["pos", _g getVariable ["cti_order_pos", [0, 0]]], ["t0", time], ["done", false]]);
		_g setVariable ["vioc_cr_role", "atk"];
		[_g, [CTI_ORDER_TAKETOWN, CTI_ORDER_TAKEHOLDTOWN] select (_o in [CTI_ORDER_TAKEHOLDTOWNS, CTI_ORDER_TAKEHOLDTOWN_AUTO]), VIOC_CR_CAP] call VIOC_CR_fnc_setOrder;
		[7] call VIOC_CR_fnc_stat;
	} forEach _teams;
	[_side, format ["[Capital] %1 a tomar %2.", if (count _teams == 1) then {"Una escuadra va"} else {format ["%1 escuadras van", count _teams]}, _tn]] call VIOC_CR_fnc_say;
	format ["%1 manda %2 a tomar %3 (%4 hombres; defensores %5)%6", _side, (_teams apply {groupId _x}) joinString ", ", _tn, _men, _def, ["", " (forzado)"] select _forced]
};

//--- [entrada]: seguimiento de una escuadra que ataca la capital
VIOC_CR_fnc_atkTrack = {
	params ["_e"];
	private _g = _e get "g";
	private _side = _e get "side";
	//--- diezmada: primero se espera a que ai_tactics la suelte; despues vuelve a su orden (si no, BECTI la mantiene para siempre)
	if (!isNull _g && {!isNil {_g getVariable "vioc_tac_man"}} && {(time - (_e get "t0")) < (VIOC_CR_ATK_MAXT + 1800)}) exitWith {};
	if (isNull _g || {({alive _x} count (units _g)) < 2}) exitWith {
		if (!isNull _g) then {
			[_g, _e get "order", _e get "pos", [CTI_ORDER_TAKETOWN, CTI_ORDER_TAKEHOLDTOWN]] call VIOC_CR_fnc_restore;
			_g setVariable ["vioc_cr_role", nil];
		};
