	};
	private _end = "";
	if ((VIOC_CR_CAP getVariable ["cti_town_sideID", -1]) == ((_side) call CTI_CO_FNC_GetSideID)) then {_end = "capital tomada"};
	//--- ai_tactics la tiene en una pinza: se espera a que la suelte (le devuelve esta orden)
	if (_end == "" && {!isNil {_g getVariable "vioc_tac_man"}} && {(time - (_e get "t0")) < (VIOC_CR_ATK_MAXT + 1800)}) exitWith {};
	private _mine = ((_g getVariable ["cti_order", -1]) in [CTI_ORDER_TAKETOWN, CTI_ORDER_TAKEHOLDTOWN]) && {(_g getVariable ["cti_order_pos", objNull]) isEqualTo VIOC_CR_CAP};
	if (_end == "" && {!_mine}) then {_end = "orden cambiada"};
