//--- ---------------------------------- bucle ----------------------------------
VIOC_CR_fnc_tick = {
	params ["_n"];
	{ [_x] call VIOC_CR_fnc_groupTick } forEach (VIOC_CR_GROUPS + []); //--- copia superficial: los mismos hashmaps
	VIOC_CR_GROUPS = VIOC_CR_GROUPS select {!(_x get "done")};
	if (count VIOC_CR_TRUCKS > 0) then {call VIOC_CR_fnc_trucksTick};
	if (VIOC_CR_PERIOD > 0 && {time >= VIOC_CR_NEXT}) then {
		private _r = [false] call VIOC_CR_fnc_dispatch;
		_r params ["_ok", "_txt", "_soon"];
		VIOC_CR_NEXT = time + ([VIOC_CR_PERIOD * 60, VIOC_CR_RETRY] select (_soon && {(VIOC_CR_PERIOD * 60) > VIOC_CR_RETRY}));
		VIOC_CR_LAST = format ["min %1: %2", round (time / 60), _txt];
		[format ["revision: %1%2", ["sin refuerzo: ", "REFUERZO "] select _ok, _txt]] call VIOC_CR_fnc_log;
	};
	if (VIOC_CR_PRIO > 0 && {(_n % 2) == 0}) then {call VIOC_CR_fnc_defTick};
	if (VIOC_CR_PRIO > 1 || {count VIOC_CR_ATK > 0}) then {call VIOC_CR_fnc_atkTick};
};

VIOC_CR_fnc_loop = {
	waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Init_Server"}};
	waitUntil {sleep 2; ({isNil {_x getVariable "cti_town_sideID"}} count CTI_Towns) == 0};
	sleep 50; //--- despues de towns_capital (40 s), airfields (30 s) y del arranque de la defensa de la mision B (60 s)
	{
		_x params ["_var", "_def", "_ok"];
		private _v = missionNamespace getVariable [_var, _def];
		if !(_v isEqualType 0 && {_v in _ok}) then {_v = _def};
		missionNamespace setVariable [_var, _v];
	} forEach [["VIOC_CAPITAL_REINF", 10, [0, 5, 10, 15]], ["VIOC_CAPITAL_REINF_MIN", 20, [10, 20, 30]], ["VIOC_CAPITAL_REINF_MAX", 3, [2, 3, 4]],
		["VIOC_CAPITAL_AI_PRIORITY", 2, [0, 1, 2]]];
	VIOC_CR_PERIOD = missionNamespace getVariable ["VIOC_CAPITAL_REINF", 10];
	VIOC_CR_MIN = missionNamespace getVariable ["VIOC_CAPITAL_REINF_MIN", 20];
	VIOC_CR_MAXG = missionNamespace getVariable ["VIOC_CAPITAL_REINF_MAX", 3];
	VIOC_CR_PRIO = missionNamespace getVariable ["VIOC_CAPITAL_AI_PRIORITY", 2];
	if (VIOC_CR_PERIOD <= 0 && {VIOC_CR_PRIO <= 0}) exitWith {["refuerzos y prioridad de la IA apagados en el lobby"] call VIOC_CR_fnc_log};
	private _t = time + 60;
	waitUntil {sleep 2; !isNull (missionNamespace getVariable ["VIOC_TC_CAPITAL", objNull]) || {isNil "VIOC_TC_RUNNING"} || {time > _t}};
	VIOC_CR_CAP = call VIOC_CR_fnc_findCapital;
	if (isNull VIOC_CR_CAP) exitWith {["no hay capital: nada que hacer"] call VIOC_CR_fnc_log};
	VIOC_CR_T0 = time;
	VIOC_CR_NEXT = time + VIOC_CR_FIRST;
	VIOC_CR_ATK_NEXT = time + VIOC_CR_ATK_START;
	[format ["capital %1 (duenio %2): refuerzos cada %3 min si hay menos de %4 defensores a %5 m, tope %6 grupos; prioridad IA %7; LAMBS %8; perf_cleanup %9, ai_tactics %10, mision B %11",
		[VIOC_CR_CAP] call VIOC_CR_fnc_tname, VIOC_CR_CAP getVariable ["cti_town_sideID", -1], VIOC_CR_PERIOD, VIOC_CR_MIN, VIOC_CR_RANGE, VIOC_CR_MAXG, VIOC_CR_PRIO,
		!isNil "lambs_wp_fnc_taskGarrison", !isNil "VIOC_PERF_AI_MAX", !isNil "VIOC_TAC_RUNNING", !isNil "VIOC_MB_LOADED"]] call VIOC_CR_fnc_log;
	private _n = 0;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		sleep VIOC_CR_TICK;
		[_n] call VIOC_CR_fnc_tick;
		_n = _n + 1;
	};
};

//--- ---------------------------------- consola ----------------------------------
VIOC_CR_fnc_info = {
	if (isNull VIOC_CR_CAP) exitWith {"VIOC capital_reinforce: todavia sin capital (arranca ~1,5 min despues de los pueblos) o apagado en el lobby"};
	private _nl = toString [10];
	private _c = VIOC_CR_CAP call VIOC_CR_fnc_p0;
	private _sid = VIOC_CR_CAP getVariable ["cti_town_sideID", -1];
	private _side = if (_sid in [CTI_WEST_ID, CTI_EAST_ID, CTI_RESISTANCE_ID]) then {(_sid) call CTI_CO_FNC_GetSideFromID} else {sideUnknown};
	private _def = if (_side isEqualTo sideUnknown) then {0} else {[_side] call VIOC_CR_fnc_defenders};
	private _t = format ["Capital %1, duenio %2: %3 defensores IA a %4 m (minimo %5). Refuerzos cada %6 min (proxima revision en %7 s), tope %8 grupos; IA %9 plazas libres; prioridad IA %10",
		[VIOC_CR_CAP] call VIOC_CR_fnc_tname, [_side] call VIOC_CR_fnc_sideName, _def, VIOC_CR_RANGE, VIOC_CR_MIN, VIOC_CR_PERIOD, round ((VIOC_CR_NEXT - time) max 0),
		VIOC_CR_MAXG, call VIOC_CR_fnc_room, VIOC_CR_PRIO];
	_t = _t + _nl + format ["Ultima revision: %1", VIOC_CR_LAST];
	{
		private _g = _x get "g";
		private _l = if (isNull _g) then {objNull} else {leader _g};
		_t = _t + _nl + format ["Grupo %1 (%2): %3, %4/%5 vivos, a %6 m del centro, posicion %7 (a %8 m), desde %9, hace %10 s%11", if (isNull _g) then {"-"} else {groupId _g},
			[_x get "side"] call VIOC_CR_fnc_sideName, _x get "state", if (isNull _g) then {0} else {{alive _x} count (units _g)}, _x get "men0",
			if (isNull _l) then {-1} else {round (_l distance2D _c)}, _x get "kind", if (isNull _l) then {-1} else {round (_l distance2D (_x get "gp"))},
			_x get "from", round (time - (_x get "t0")), if ((_x get "state") == "orphan") then {format [" (sin capital hace %1 s)", round (time - (_x get "tO"))]} else {""}];
	} forEach VIOC_CR_GROUPS;
	{
		private _v = _x get "v";
		_t = _t + _nl + format ["Camion %1: vuelve %2, hace %3 s", if (isNull _v) then {"(destruido)"} else {typeOf _v}, _x get "sent", round (time - (_x get "t"))];
	} forEach VIOC_CR_TRUCKS;
	{
		_t = _t + _nl + format ["Defensa IA: %1 (%2) desde hace %3 s, orden %4", groupId (_x get "g"), _x get "side", round (time - (_x get "t0")), (_x get "g") getVariable ["cti_order", -1]];
	} forEach VIOC_CR_DEF;
	{
		_t = _t + _nl + format ["Ataque IA: %1 (%2) desde hace %3 s, orden %4", groupId (_x get "g"), _x get "side", round (time - (_x get "t0")), (_x get "g") getVariable ["cti_order", -1]];
	} forEach VIOC_CR_ATK;
	_t = _t + _nl + format ["Amenaza: %1 enemigos (%2, hace %3 s); proximo ataque prioritario en %4 s", VIOC_CR_THREAT select 1, VIOC_CR_THREAT select 0,
		if ((VIOC_CR_THREAT select 2) < 0) then {-1} else {round (time - (VIOC_CR_THREAT select 2))}, round ((VIOC_CR_ATK_NEXT - time) max 0)];
	if (!isNil {VIOC_CR_CAP getVariable "vioc_mb_key"}) then {
		_t = _t + _nl + format ["Mision B: clave %1, guarnicion presente %2 s mas, hecha hace %3 s", VIOC_CR_CAP getVariable ["vioc_mb_key", false],
			round (((VIOC_CR_CAP getVariable ["vioc_mb_hold", -1]) - time) max 0), if ((VIOC_CR_CAP getVariable ["vioc_mb_made", -1]) < 0) then {-1} else {round (time - (VIOC_CR_CAP getVariable ["vioc_mb_made", -1]))}];
	};
	_t + _nl + format ["INFO %1 [grupos, en camion, a pie, hombres, grupos borrados, camiones borrados, defensas IA, ataques IA]", VIOC_CR_INFO]
};

//--- Un grupo de refuerzo YA (sin mirar el minimo ni la espera; con los topes y el presupuesto)
