//--- Marcadores locales (solo en la maquina que lo ejecuta): grupos (jefe), sus posiciones y camiones; otra vez para borrarlos
VIOC_CR_fnc_markers = {
	if (count VIOC_CR_MK > 0) exitWith {
		{ deleteMarkerLocal _x } forEach VIOC_CR_MK;
		VIOC_CR_MK = [];
		"marcadores borrados"
	};
	{
