			VIOC_CR_MK pushBack _p;
		};
	} forEach VIOC_CR_GROUPS;
	{
		private _v = _x get "v";
		if (!isNull _v) then {
			private _m = createMarkerLocal [format ["vioc_cr_t%1", _forEachIndex], getPosATL _v];
			_m setMarkerTypeLocal "mil_dot";
			_m setMarkerColorLocal "ColorOrange";
